14	    /// Cached for the life of the connection: the daemon answers this by running
15	    /// `whoami` against the Hub every time, which is a network round trip to learn
16	    /// something that changes when the user says so.
17	    func robotHFAccount(refresh: Bool = false) async throws -> HFAuthStatus {
18	        if !refresh, let cached = hfAccountCache {
19	            return cached
20	        }
21	        let status = try await withHFAuthClient { try await $0.hfAuthStatus() }
22	        hfAccountCache = status
23	        return status
24	    }
25	
26	    /// Hands the robot a token and asks the relay to pick it up at once, rather
27	    /// than on its next retry.
28	    ///
29	    /// The returned refresh says whether anything actually restarted — on
30	    /// `skipped` there is no state change coming, so a caller must not wait for
31	    /// one.
32	    @discardableResult
33	    func linkRobot(token: String) async throws -> RelayRefresh {
34	        let username = try await withHFAuthClient { try await $0.saveHFToken(token) }
35	        // `save-token` validated the token against the Hub to answer at all, so
36	        // the account is known — asking for the status again would repeat that
37	        // same `whoami`.
38	        hfAccountCache = HFAuthStatus(isLoggedIn: true, username: username)
39	        return try await withHFAuthClient { try await $0.refreshRelay() }
40	    }
